  str_quest_base_daily_reset_tips = "日常任務已重設",
  str_quest_base_awards_info_look = "獎勵預覽",
  str_quest_base_story_chapter_index = "第%s章",
  str_quest_base_story_all_chapter_clean = "全章節任務完成！",
  str_quest_base_story_current_chapter_clean = "本章任務已全部完成",
  str_quest_base_story_click_lock_chapter = "完成前一章劇情任務後開放",
  str_quest_base_desc_101 = "臨空者號的主人，這是你揚帆出航的起點。意料之外的收穫、猝然無措的變故、柳暗花明的轉機，和迫不得已的成長……變強總是伴隨著劇痛，如果無法逃避那就享受這份愉悅吧。一切苦難，都將在未來開花結果。\n——伯利恆",
  str_quest_base_desc_102 = "初入世界的體驗很微妙，不是嗎？我祝你沉穩而理智地應對危機，珍惜羈絆。你見到的所有人與物，都是艾斯特拉的一部分，都是最終要歸於極光的一部分，甚至你自己……接受，理解，回饋，然後繼續成長吧。\n——伯利恆",
  str_quest_base_desc_103 = "來自過去的回音再次迴盪起來，同胞、敵人、戰友，紛至沓來。要如何面對看似希望的轉機與跌落谷底的挫折，如何權衡個人仇恨與新群體的「使命」，是你必須用血與淚學會的課題。\n——伯利恆",
  str_quest_base_desc_104 = "現在，理解你的目標了嗎？你又是否感受到，來自族群之外的認同？前方是光靈最後的都市，與天空接壤的浮島，你將在那裡找到新的羈絆，邁出更堅定的一步，朝刺破黑暗之旅前進。\n——伯利恆",
  str_quest_base_desc_105 = "不斷受挫，不斷戰鬥，像從出生起便不知退卻為何物的猛獸，像揮舞刀劍戰死沙場的勇者。往事會繼續滾滾襲來，要你直視最大的恐懼。看著她的臉，告訴我：你看到的是誰？\n——伯利恆",
  str_quest_base_desc_106 = "焦慮嗎？如同極光所揭示的那樣，你快要到達谷底，那裡是憤懣與仇怨匯聚的泥潭、失敗和屈辱構築的鐵牢。但也只有從那裡，你才能拾獲真正的力量——不是鋼筋鐵骨，而是開拓的眼與心。\n——伯利恆",
  str_quest_base_desc_107 = "我們的隔空對話終於要來到新的階段了，空裔。你無法理解我的角色，我也無法理解，那是憑藉語焉不詳的徵兆書寫的隻字片語。極光在暗淡，白夜城上有展翼的絕望之人——不是踏過她，就是一切到此為止。\n——伯利恆",
  str_quest_base_desc_108 = "即便是在最黑暗的深淵裡，你也能倖存到驗證「預言」的那天。我是這樣相信著，謹遵內心最難以言喻的直覺。抓住機會，空裔，讓那座黑色堡壘回到原本該在的地方！\n——伯利恆",
  str_quest_base_desc_109 = "我們有兩個故鄉：一個在腳下，一個在心裡。幸運的人，會發現兩者並無差別；但大多數苦難的靈魂則不斷掙扎於兩者之間，甚至再無機會觸碰記憶深處的那片土地。就算心有不甘，也別無他法。\n ——伯利恆",
  str_quest_base_desc_110 = "我相信那片土地會讓你成長，讓你記起許多事的同時，又能平靜地放下。旅途的盡頭在前方，盡情釋放你的怨懟與仇恨，然後讓它煙消雲散吧。我希望在我們碰面之時，你已成為嶄新的自己。\n ——伯利恆",
  str_quest_base_desc_111 = "永夜，那是每個光靈都不願意接近的領域，是被黑暗侵蝕的深淵。在這晝與夜的幕間，也請抓住那轉瞬即逝的機會，巨像的主人，希望你能劃破黑暗，最終得償所願。\n\n——伯利恆",
  str_quest_base_desc_112 = "希望往往伴隨著考驗，如荊棘覆生的花朵。如果做好了遍體鱗傷的準備，那就再次回到你出發的地方吧。去尋找，去失去，去絕望，再重新仰起你的頭顱。\n\n——伯利恆",
  str_quest_base_desc_113 = "真相的利刃貫穿了胸膛，撕裂了脆弱的心房。「怎會如此？」「不可能是這樣！」驚詫，懷疑，憤懣，然後在迷失的深淵旁凝視虛空。我看不見你的選擇，空裔，我什麼都看不見。 \n\n——伯利恆",
  str_quest_base_desc_114 = "每個人都在自己的生命裡不斷求知。你是幸運的卻也是悲哀的，命運給你留出了更廣闊的空間，你可以走得比常人更遠，可路上卻沒有旁人。我不知道你會走向哪裡，因為那注定在我視線之外。\n——伯利恆",
  str_quest_base_desc_115 = "發現了嗎，你開始遇到越來越多的人。他們來自不同的地方，去往不同的地方，只在道路上的某個節點，與你撞在一起。天穹之下住著那麼多人，頭頂太陽的幸運兒沐浴著最豐盛的日光，可遲暮夕陽旁頓足的孩子們，卻站在離太陽最近的位置。\n——伯利恆",
  str_quest_base_desc_116 = "與宿敵同行，這是何等諷刺的命運。無論前方是火海還是深坑，除了與夥伴們一起面對外，你似乎別無選擇。\n——伯利恆",
  str_quest_base_desc_117 = "戰場是陰謀家的舞台，無知的觀眾從四面八方湧來。無垠黑夜近在咫尺之際，光靈們仍未真正從各自的美夢中清醒過來。\n——伯利恆",
  str_quest_base_desc_118 = "權力更迭之際，不曾被命運眷顧之人，卻在眾人的矚目中登上世界舞台。然而，野心是戰場上最無用的兵器，唯有殺死過去的自己，才能從政治的漩渦中脫險重生。\n——伯利恆",
  str_quest_base_desc_119 = "力量到底是源於自我的驅動，還是他者的賦予？當目睹了強大的身軀在泥沼中苦掘墳墓之時，你逐漸領悟到，脆弱才是生命的本質。\n——伯利恆",
  str_quest_base_desc_120 = "一個陌生的存在，跨越六百多年終與啟光攜手。是該翻開歷史的書頁尋找可能，還是摒棄過往開創新的道路？這是當下的疑問，也是困擾了無數代光靈的謎題。\n——伯利恆",
  str_quest_base_desc_121 = "與夥伴度過無數歡樂時光的你，不曾想到告別的時刻竟來得那樣倉促。「來自過去的訊號」再度亮起，這一次，你必須成長，前往未知的遺跡探索自己的過去。\n——伯利恆",
  str_quest_base_desc_122 = "要在前行之路上豎起一座座燈塔。我，北境女王如是說。\n——伯利恆",
