  str_quest_base_achieve_type_407_space = "巨像",
  str_quest_base_achieve_finish_list_title = "以下任務已完成",
  str_quest_base_desc_123 = "你已見識極夜，是否明確了心中的信念？這世間太多人陷入黑暗的僵局，追尋一個縹緲的希望。可對你來說，它並不虛幻。\n你始終會抓住它，因為這個故事，就是從你踏上這條英雄之路開始。你將護衛那光點，希望也會為你而續。相信這點，堅定不移地走下去吧。\n——伯利恆",
